select
*
from USERPROFILE
where USERNAME = #{username,jdbcType=VARCHAR}
AND PASSWORD = #{password,jdbcType=VARCHAR}

select * from(
SELECT HR_DEPT_NAME site ,USERNUMBER employeeId,USERNAME employeeName

from CUX_ERP_HR_HRDETAIL@JCD_DEMO WHERE CREATETIME > SYSDATE-30
and USERNUMBER = #{userid,jdbcType=VARCHAR}
order by CREATETIME desc
             ) where rownum=1
